import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"よくある質問","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md","lastUpdated":1793464466000}`),a={name:`reference/faq.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to “よくある質問”">​</a></h1><h2 id="ページごとに設定が必要ですか" tabindex="-1">ページごとに設定が必要ですか？ <a class="header-anchor" href="#ページごとに設定が必要ですか" aria-label="Permalink to “ページごとに設定が必要ですか？”">​</a></h2><p>共通タグで基本のページ情報を自動取得します。ページごとの必須設定はありません。JSON-LDやメタデータの内容は確認してください。</p><h2 id="生の表示秒数をそのまま関心とみなしますか" tabindex="-1">生の表示秒数をそのまま関心とみなしますか？ <a class="header-anchor" href="#生の表示秒数をそのまま関心とみなしますか" aria-label="Permalink to “生の表示秒数をそのまま関心とみなしますか？”">​</a></h2><p>表示時間は観測値です。最低時間を満たした閲覧をAPIで選び、関心はページの文脈等も含めて判断します。長いほど購入確率が高いという換算ではありません。</p><h2 id="aiでオファーの文章を作りますか" tabindex="-1">AIでオファーの文章を作りますか？ <a class="header-anchor" href="#aiでオファーの文章を作りますか" aria-label="Permalink to “AIでオファーの文章を作りますか？”">​</a></h2><p>作りません。文章・画像・JavaScriptは事前登録します。入力からの判定質問も固定テンプレートで組み立てます。</p><h2 id="「何を伝えたいか」と表示タイトルは同じですか" tabindex="-1">「何を伝えたいか」と表示タイトルは同じですか？ <a class="header-anchor" href="#「何を伝えたいか」と表示タイトルは同じですか" aria-label="Permalink to “「何を伝えたいか」と表示タイトルは同じですか？”">​</a></h2><p>前者は判定の文脈を説明する入力です。表示タイトルは実際に見せる文言です。施策名はさらに別の管理用名称です。</p><h2 id="同じユーザーで複数サイトを使えますか" tabindex="-1">同じユーザーで複数サイトを使えますか？ <a class="header-anchor" href="#同じユーザーで複数サイトを使えますか" aria-label="Permalink to “同じユーザーで複数サイトを使えますか？”">​</a></h2><p>使えます。1つのアカウントが複数サイトに所属し、ヘッダーで切り替えます。権限はサイトごとに異なることがあります。</p><h2 id="招待メールは自動送信されますか" tabindex="-1">招待メールは自動送信されますか？ <a class="header-anchor" href="#招待メールは自動送信されますか" aria-label="Permalink to “招待メールは自動送信されますか？”">​</a></h2><p>初期版では手動リンク共有です。Cloudflare Accessの入場用メールコードとは別の機能です。</p><h2 id="管理トークンはもう必要ありませんか" tabindex="-1">管理トークンはもう必要ありませんか？ <a class="header-anchor" href="#管理トークンはもう必要ありませんか" aria-label="Permalink to “管理トークンはもう必要ありませんか？”">​</a></h2><p>本番の最初のSuperuser登録に使います。移行後の共通パスワードや復旧の裏口には使いません。Accessに連携したPreviewの初回登録では不要です。</p><h2 id="表示回数は全端末で共有されますか" tabindex="-1">表示回数は全端末で共有されますか？ <a class="header-anchor" href="#表示回数は全端末で共有されますか" aria-label="Permalink to “表示回数は全端末で共有されますか？”">​</a></h2><p>共有しません。ブラウザ内の有効な履歴に基づきます。サーバーの閲覧者IDで全端末を追跡する方式ではありません。</p><h2 id="previewのパスキーを本番で使えますか" tabindex="-1">Previewのパスキーを本番で使えますか？ <a class="header-anchor" href="#previewのパスキーを本番で使えますか" aria-label="Permalink to “Previewのパスキーを本番で使えますか？”">​</a></h2><p>OriginとDBが異なるため、同じ登録をそのまま移す扱いではありません。本番で別途登録します。</p><h2 id="本番にも常にaccessが必要ですか" tabindex="-1">本番にも常にAccessが必要ですか？ <a class="header-anchor" href="#本番にも常にaccessが必要ですか" aria-label="Permalink to “本番にも常にAccessが必要ですか？”">​</a></h2><p>今回の確認環境はAccessで保護します。本番の管理画面はアプリのパスキーと権限で保護し、必要に応じてAccess等も併用します。配信APIの公開範囲と混同しないでください。</p><h2 id="成果や購入率はどこで見られますか" tabindex="-1">成果や購入率はどこで見られますか？ <a class="header-anchor" href="#成果や購入率はどこで見られますか" aria-label="Permalink to “成果や購入率はどこで見られますか？”">​</a></h2><p>現在は成果集計やA/Bテストを提供していません。ホームは設定状態の表示です。Jevの判定値を成果として表示するものではありません。</p><h2 id="ヘルプはどこで編集できますか" tabindex="-1">ヘルプはどこで編集できますか？ <a class="header-anchor" href="#ヘルプはどこで編集できますか" aria-label="Permalink to “ヘルプはどこで編集できますか？”">​</a></h2><p>GitHubリポジトリの<code>help/</code>以下のMarkdownです。各ページの編集リンク、またはIssuesから提案できます。公開手順は<a href="./../operations/help-site">ヘルプサイトの保守</a>を参照してください。</p>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};